text.sample:
program ReadOutEvents;
  driver_exception = LMS;

  procedure OnActivate();
  var
    s : string;
  begin
    repeat
      core.DriverQueryProc( 'LMS', 'get_event', &s );
      core.DebugOutput( 'Event: ', s );
    until s = '';
  end_procedure;

end_program;

core.DriverQueryProc( 'LMS', 'zone create Main', &Error );
...
core.DriverQueryProc( 'LMS', 'zone commit', &Error );

core.DriverQueryProc( 'LMS', 'zone change Auxiliary', &Error );
core.DriverQueryProc( 'LMS', 'zone copy_from Main', &Error );
...
core.DriverQueryProc( 'LMS', 'zone abort', &Error );

core.DriverQueryProc( 'LMS', 'zone change Main', &Error );

core.DriverQueryProc( 'LMS', 'zone switch on', &Error );
core.DriverQueryProc( 'LMS', 'zone angle_from 10', &Error );
core.DriverQueryProc( 'LMS', 'zone angle_to 150', &Error );
core.DriverQueryProc( 'LMS', 'zone distance_from 3000', &Error );
core.DriverQueryProc( 'LMS', 'zone near_limit 50', &Error );
core.DriverQueryProc( 'LMS', 'zone far_limit 300', &Error );
core.DriverQueryProc( 'LMS', 'zone beam_count 10', &Error );
core.DriverQueryProc( 'LMS', 'zone gap_count 2', &Error );
core.DriverQueryProc( 'LMS', 'zone movement_threshold 25', &Error );

core.DriverQueryProc( 'LMS', 'zone commit', &Error );
